/* Overview remains the action dashboard; Repair jobs is the searchable history and job register. */
let repairRegisterScope='',repairRegisterPage=1;
let repairRegisterFilters={search:'',bucket:'all',stage:'all',agency:'all',property:'all',category:'all',priority:'all',sort:'newest'};
function repairLifecycle(j){if(j.status==='Cancelled')return 'cancelled';if(role==='tenant'&&j.status==='Completed'||jobStage(j)==='closed')return 'closed';return 'open'}
function repairRegisterJobs(){const f=repairRegisterFilters,q=f.search.trim().toLowerCase();return visibleJobs().filter(j=>{const p=property(j.property),a=state.agencies.find(a=>a.id===j.agency),pm=state.members?.find(m=>m.id===p?.manager);return (!q||`${j.ref} ${j.title} ${j.category} ${p?.name} ${p?.address} ${a?.name} ${pm?.name||''}`.toLowerCase().includes(q))&&(f.bucket==='all'||repairLifecycle(j)===f.bucket)&&(f.stage==='all'||f.stage===(role==='sevlink'?'stage:'+jobStage(j):'status:'+jobStatusLabel(j)))&&(role!=='sevlink'||f.agency==='all'||j.agency===f.agency)&&(f.property==='all'||j.property===f.property)&&(f.category==='all'||j.category===f.category)&&(f.priority==='all'||j.priority===f.priority)}).sort((a,b)=>{if(f.sort==='property')return (property(a.property)?.address||property(a.property)?.name||'').localeCompare(property(b.property)?.address||property(b.property)?.name||'');const at=Date.parse(a.createdAt)||0,bt=Date.parse(b.createdAt)||0;return f.sort==='oldest'?at-bt||a.ref.localeCompare(b.ref,undefined,{numeric:true}):bt-at||b.ref.localeCompare(a.ref,undefined,{numeric:true})})}
function setRepairRegisterBucket(bucket){repairRegisterFilters.bucket=bucket;repairRegisterPage=1;renderRepairRegisterResults()}
function resetRepairRegister(){repairRegisterFilters={search:'',bucket:'all',stage:'all',agency:'all',property:'all',category:'all',priority:'all',sort:'newest'};repairRegisterPage=1;renderRepairRegister()}
function renderRepairRegister(){const scope=[role,agency,activeMember,tenant].join(':');if(scope!==repairRegisterScope){repairRegisterScope=scope;repairRegisterFilters={search:'',bucket:'all',stage:'all',agency:'all',property:'all',category:'all',priority:'all',sort:'newest'};repairRegisterPage=1}const jobs=visibleJobs(),f=repairRegisterFilters;const option=(value,label,selected)=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(label)}</option>`;const statuses=role==='sevlink'?stages.map(([key,title])=>['stage:'+key,title]):[...new Set(jobs.map(jobStatusLabel))].sort().map(s=>['status:'+s,s]);const props=state.properties.filter(p=>canSeeProperty(p)&&(role!=='sevlink'||f.agency==='all'||p.agency===f.agency));app.innerHTML=heading(role==='tenant'?'Your repair history.':'Repair job register.',role==='sevlink'?'Search every submitted job across agencies, including closed and cancelled records.':'Search the repairs and history for properties linked to your profile.')+`<div class="panel"><div class="filters repair-register-search"><input id="repairRegisterSearch" type="search" placeholder="Search reference, property address or repair…" aria-label="Search repair jobs" value="${esc(f.search)}"><button class="secondary" onclick="resetRepairRegister()">Clear filters</button></div><div class="repair-register-filters">${role==='sevlink'?`<label>Agency<select id="repairRegisterAgency">${option('all','All agencies',f.agency)}${state.agencies.filter(a=>!a.archivedForAgencyOnly).map(a=>option(a.id,a.name,f.agency)).join('')}</select></label>`:''}<label>Property<select id="repairRegisterProperty">${option('all','All properties',f.property)}${props.map(p=>option(p.id,p.address||p.name,f.property)).join('')}</select></label><label>${role==='sevlink'?'Pipeline stage':'Status'}<select id="repairRegisterStage">${option('all','All statuses',f.stage)}${statuses.map(([v,l])=>option(v,l,f.stage)).join('')}</select></label><label>Category<select id="repairRegisterCategory">${option('all','All categories',f.category)}${[...new Set(jobs.map(j=>j.category))].sort().map(c=>option(c,c,f.category)).join('')}</select></label><label>Priority<select id="repairRegisterPriority">${option('all','All priorities',f.priority)}${['Not set','Normal','High','Urgent'].map(v=>option(v,v,f.priority)).join('')}</select></label><label>Sort by<select id="repairRegisterSort">${[['newest','Newest first'],['oldest','Oldest first'],['property','Property address']].map(([v,l])=>option(v,l,f.sort)).join('')}</select></label></div><div id="repairRegisterResults" style="margin-top:20px"></div></div>`;$('#repairRegisterSearch').oninput=e=>{f.search=e.target.value;repairRegisterPage=1;renderRepairRegisterResults()};for(const [name,key] of [['Agency','agency'],['Property','property'],['Stage','stage'],['Category','category'],['Priority','priority'],['Sort','sort']]){const input=$('#repairRegister'+name);if(input)input.onchange=e=>{f[key]=e.target.value;repairRegisterPage=1;if(key==='agency'){f.property='all';renderRepairRegister()}else renderRepairRegisterResults()}}renderRepairRegisterResults()}
function renderRepairRegisterResults(){if(view!=='requests')return;const all=visibleJobs(),jobs=repairRegisterJobs(),pages=Math.max(1,Math.ceil(jobs.length/25));repairRegisterPage=Math.min(repairRegisterPage,pages);const slice=jobs.slice((repairRegisterPage-1)*25,repairRegisterPage*25);$('#repairRegisterResults').innerHTML=`<div class="toolbar repair-register-buckets">${[['all','All jobs'],['open','Open'],['closed','Closed'],['cancelled','Cancelled']].map(([key,title])=>`<button class="${repairRegisterFilters.bucket===key?'primary':'secondary'}" onclick="setRepairRegisterBucket('${key}')">${title} · ${key==='all'?all.length:all.filter(j=>repairLifecycle(j)===key).length}</button>`).join('')}</div><p class="muted" aria-live="polite">${jobs.length} matching jobs${jobs.length?' · showing '+((repairRegisterPage-1)*25+1)+'–'+Math.min(repairRegisterPage*25,jobs.length):''}</p><div class="tablewrap"><table class="phone-cards repair-register-table"><thead><tr><th>PROPERTY / REPAIR</th>${role==='sevlink'?'<th>AGENCY / PM</th>':''}<th>STATUS</th><th>PRIORITY</th><th>REPORTED</th><th></th></tr></thead><tbody>${slice.map(j=>{const p=property(j.property),a=state.agencies.find(a=>a.id===j.agency),pm=state.members?.find(m=>m.id===p?.manager);return `<tr><td data-label="PROPERTY / REPAIR"><strong>${esc(p?.address||p?.name||'Property not recorded')}</strong><small>${esc(p?.name)}</small><p style="margin:7px 0 2px;color:var(--ink)">${esc(j.title)}</p><small>${esc(j.ref)} · ${esc(j.category)}</small></td>${role==='sevlink'?`<td data-label="AGENCY / PM"><strong>${esc(a?.name||'Agency not recorded')}</strong><small>PM: ${esc(pm?.name||a?.contact||'Unassigned')}</small></td>`:''}<td data-label="STATUS">${badge(role==='sevlink'?(stages.find(s=>s[0]===jobStage(j))?.[1]||jobStatusLabel(j)):jobStatusLabel(j))}${role==='sevlink'?'<small style="display:block;margin-top:7px">'+esc(nextAction(j)||'View job record')+'</small>':''}</td><td data-label="PRIORITY">${badge(j.priority||'Not set')}${j.callout&&role!=='tenant'?'<br><small>Call-out</small>':''}</td><td data-label="REPORTED">${j.createdAt?esc(date(j.createdAt)):'Not recorded'}</td><td data-label="OPEN"><button class="secondary" onclick="jobDetail('${j.id}','comments')">Open job →</button></td></tr>`}).join('')||`<tr><td colspan="${role==='sevlink'?6:5}" class="empty">${all.length?'No jobs match these filters.':'No repair jobs yet.'}</td></tr>`}</tbody></table></div>${pages>1?`<div class="toolbar" style="margin-top:18px"><button class="secondary" ${repairRegisterPage===1?'disabled':''} onclick="repairRegisterPage--;renderRepairRegisterResults()">← Previous</button><span>Page ${repairRegisterPage} of ${pages}</span><button class="secondary" ${repairRegisterPage===pages?'disabled':''} onclick="repairRegisterPage++;renderRepairRegisterResults()">Next →</button></div>`:''}`}
const renderBeforeRepairRegister=render;
render=function(){renderBeforeRepairRegister();if(state&&view==='requests'&&state.agencies.length)renderRepairRegister()};
